import{c as o,Q as a,j as t,m as r}from"./chunks/framework.BPKcPtvA.js";const y=JSON.parse('{"title":"TOTP recovery codes","description":"What recovery codes are, how to use them, and what to do if you lose them.","frontmatter":{"title":"TOTP recovery codes","description":"What recovery codes are, how to use them, and what to do if you lose them."},"headers":[],"relativePath":"auth/totp-recovery.md","filePath":"auth/totp-recovery.md"}'),n={name:"auth/totp-recovery.md"};function c(d,e,s,i,l,h){return a(),t("div",null,[...e[0]||(e[0]=[r('<p>When you enroll a TOTP authenticator app, GateKeeper generates 8 recovery codes. These are backup codes you can use to log in if you lose access to your authenticator app.</p><h2 id="using-a-recovery-code" tabindex="-1">Using a recovery code <a class="header-anchor" href="#using-a-recovery-code" aria-label="Permalink to &quot;Using a recovery code&quot;">​</a></h2><p>On the TOTP challenge page (<code>/login/totp</code>), click <strong>Use a recovery code instead</strong>. Enter one of your saved codes at <code>/login/totp/recovery</code>.</p><p>Each code works exactly once. After you use it, it is permanently invalidated.</p><h2 id="format" tabindex="-1">Format <a class="header-anchor" href="#format" aria-label="Permalink to &quot;Format&quot;">​</a></h2><p>Recovery codes look like this: <code>aB-3x-Qz-7m-Kp</code>. They are case-sensitive. GateKeeper stores only the argon2id hash of each code, so they cannot be recovered from the database.</p><h2 id="what-to-do-if-you-run-out-of-codes" tabindex="-1">What to do if you run out of codes <a class="header-anchor" href="#what-to-do-if-you-run-out-of-codes" aria-label="Permalink to &quot;What to do if you run out of codes&quot;">​</a></h2><p>If you have used all your recovery codes and cannot log in, an admin can revoke your TOTP enrollment from <code>/admin/users/:id</code>. After that, you can log in with email OTP and re-enroll TOTP if you want.</p><p>If you are the only admin and have lost access, you will need to manually update the database. Connect to the SQLite file and set <code>totp_enabled=0</code> for your admin user record.</p><h2 id="what-to-do-if-you-lose-your-codes" tabindex="-1">What to do if you lose your codes <a class="header-anchor" href="#what-to-do-if-you-lose-your-codes" aria-label="Permalink to &quot;What to do if you lose your codes&quot;">​</a></h2><p>If you still have access to your authenticator app, log in normally and then go to <code>/profile/totp/enroll</code> to re-enroll. This generates a new set of recovery codes and invalidates the old ones.</p><p>If you have neither your authenticator app nor your recovery codes, contact your admin to revoke your TOTP enrollment.</p><h2 id="keeping-codes-safe" tabindex="-1">Keeping codes safe <a class="header-anchor" href="#keeping-codes-safe" aria-label="Permalink to &quot;Keeping codes safe&quot;">​</a></h2><p>Store recovery codes in a password manager, printed and locked away, or another secure offline location. The goal is to have them available even if the device with your authenticator app is lost or broken.</p>',14)])])}const p=o(n,[["render",c]]);export{y as __pageData,p as default};
